/**
 * `[src:<segment id>]` markers: the handle from a recalled fact to the source
 * passage it was extracted from.
 *
 * A fact that `memory_ingest` extracted from a longer text keeps a link to that
 * text (its segment). Recall and briefing output carries the segment id next to
 * such a fact (list formats), or in a sources line after the text (formats a
 * model rewrites: summary, answer), so an agent can read the passage behind a
 * thin headline with `memory_expand`, whatever format it asked for. Segment ids
 * are generated by the server (32 hex characters), never by an agent.
 */

const MARKER_PREFIX = '[src:';

/** The marker for one segment: `[src:<id>]`. */
export function sourceMarker(segmentId: string): string {
  return `${MARKER_PREFIX}${segmentId}]`;
}

/**
 * The line that follows rewritten recall text (summary, answer) when any of the
 * facts behind it has a source: the distinct segment ids in first-seen order, or ''
 * when none has one.
 */
export function sourcesLine(segmentIds: Iterable<string | null>): string {
  const unique = [...new Set([...segmentIds].filter((id): id is string => id !== null && id !== ''))];
  if (unique.length === 0) return '';
  return `Sources (pass one to memory_expand as segment_id to read the passage): ${unique.map(sourceMarker).join(' ')}`;
}

/**
 * A segment id as an agent may pass it back: the bare id, `src:<id>` or the whole
 * `[src:<id>]` marker. Anything else is returned trimmed and unchanged.
 */
export function segmentIdFromMarker(value: string): string {
  const trimmed = value.trim();
  const match = /^\[?src:([^\]\s]+)\]?$/.exec(trimmed);
  return match ? match[1] : trimmed;
}
